#define MAXDIST 100.f
#define MAXSTEP 32
#define minDist .001

struct Ray
{
    vec3 ro;
    vec3 rd;
};

//https://iquilezles.org/articles/distfunctions/
float sdSphere(vec3 pos, vec3 center, float radius){
    return length(pos-center)-radius;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

vec3 getColor( in vec3 ro, in vec3 rd)
{
    vec3 center = vec3(0.,0.,1.2);
    int count = 0;
    float distFromSphere = sdSphere(rd,center,.4);

    //either it hits 
    while(distFromSphere > minDist && count < MAXSTEP){
    //the march step

            count++;
            ro = ro+rd * distFromSphere;
            distFromSphere = sdSphere(ro,center,.4);

        // or it exceeds the maxdist
        if(length(ro+rd) < MAXDIST){
            return vec3(.0);
        }
    }
    //idk what this does honestly but it looks better
    center = vec3(-.2,.2,-.2);

    //maybe lighting??
    float something = dot(normalize(ro+rd-center),vec3(abs(sin(iTime)),abs(cos(iTime)),.5));

    //adding some more color
    return vec3(something+.4,something+.2,something+.6);
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // most of this initial stuf is from https://blog.demofox.org/2020/05/25/casual-shadertoy-path-tracing-1-basic-camera-diffuse-emissive/
    vec3 screen = vec3((fragCoord/iResolution.xy) * 2.0f - 1.0f, 1.0f);
    // correct for aspect ratio
    float aspectRatio = iResolution.x / iResolution.y;
    screen.y /= aspectRatio;

    vec3 camera = vec3(0.1*sin(iTime),0.1*cos(iTime),.0);
    Ray ray;


    ray.ro = camera;
    ray.rd = normalize(screen - ray.ro);

    vec3 col = vec3(getColor(ray.ro,ray.rd));

    fragColor = vec4(col,1.0);
}
